node -e "
const { renderToString } = require('@antv/infographic/ssr');
(async () => {
  try {
    const syntax = \`infographic chart-line-plain-text
data
  title Temperature Anomaly
  values
    - label 1700
      value 0.00
    - label 1750
      value -0.02
    - label 1800
      value 0.10
    - label 1850
      value 0.40
    - label 1900
      value 0.52
    - label 1950
      value 0.68
    - label 2000
      value 1.25
    - label 2020
      value 1.70
theme
  palette #1a3a5c #c0392b\`;
    const svg = await renderToString(syntax, { width: 1200, height: 600 });
    console.log('SVG length:', svg.length);
    console.log(svg.substring(0, 500));
  } catch(e) {
    console.error('Error:', e.message);
    console.error(e.stack);
  }
})();
"

