const { renderToString } = require('@antv/infographic/ssr');
const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

const A0_W = 4961;
const A0_H = 7016;

// Construct the temperature reconstruction data (decadal resolution, 1700–2020)
const tempData = [
  { year: 1700, anomaly: -0.03 }, { year: 1710, anomaly: 0.00 }, { year: 1720, anomaly: -0.02 },
  { year: 1730, anomaly: 0.01 },  { year: 1740, anomaly: -0.01 }, { year: 1750, anomaly: -0.04 },
  { year: 1760, anomaly: 0.02 },  { year: 1770, anomaly: 0.00 },  { year: 1780, anomaly: 0.03 },
  { year: 1790, anomaly: 0.08 },  { year: 1800, anomaly: 0.14 },  { year: 1810, anomaly: 0.20 },
  { year: 1820, anomaly: 0.22 },  { year: 1830, anomaly: 0.28 },  { year: 1840, anomaly: 0.36 },
  { year: 1850, anomaly: 0.42 },  { year: 1860, anomaly: 0.45 },  { year: 1870, anomaly: 0.47 },
  { year: 1880, anomaly: 0.50 },  { year: 1890, anomaly: 0.52 },  { year: 1900, anomaly: 0.54 },
  { year: 1910, anomaly: 0.58 },  { year: 1920, anomaly: 0.62 },  { year: 1930, anomaly: 0.66 },
  { year: 1940, anomaly: 0.70 },  { year: 1950, anomaly: 0.72 },  { year: 1960, anomaly: 0.78 },
  { year: 1970, anomaly: 0.86 },  { year: 1980, anomaly: 0.98 },  { year: 1990, anomaly: 1.12 },
  { year: 2000, anomaly: 1.30 },  { year: 2010, anomaly: 1.50 },  { year: 2020, anomaly: 1.70 }
];

function buildChartSyntax() {
  const values = tempData.map(d => `    - label ${d.year}
      value ${d.anomaly}`).join('\n');

  return `infographic chart-line-plain-text
data
  title Global SST Anomaly (1700–2020)
  desc Sclerosponge Sr/Ca reconstruction vs. instrumental record
  values
${values}
theme
  palette #1a3a5c #c0392b #e67e22
  base #0a1628`;
}

function buildPosterHTML(chartSVG) {
  // Clean up the SVG — remove XML declarations and fix font for academic context
  let cleanSVG = chartSVG
    .replace(/<\?xml[^?]*\?>/g, '')
    .replace(/<\?xml-stylesheet[^?]*\?>/g, '')
    .replace(/font-family="[^"]*"/g, 'font-family="Helvetica Neue, Arial, sans-serif"');

  // Replace font references in style tags
  cleanSVG = cleanSVG.replace(/font-family:[^;"]*Alibaba PuHuiTi[^;"]*/g, 'font-family: "Helvetica Neue", Arial, sans-serif');

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    width: ${A0_W}px;
    height: ${A0_H}px;
    font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
    background: linear-gradient(170deg, #080e18 0%, #0a1628 15%, #0d1f3c 50%, #0a1628 85%, #080e18 100%);
    color: #e8edf2;
    overflow: hidden;
    display: flex;
    flex-direction: column;
  }

  /* --- HEADER --- */
  .poster-header {
    padding: 80px 100px 40px 100px;
    border-bottom: 2px solid rgba(26,58,92,0.5);
    background: linear-gradient(180deg, rgba(10,22,40,0.95) 0%, rgba(13,31,60,0.9) 100%);
  }

  .poster-header .title {
    font-size: 64px;
    font-weight: 800;
    line-height: 1.15;
    color: #ffffff;
    letter-spacing: -0.5px;
    max-width: 4200px;
  }

  .poster-header .title em {
    font-style: italic;
    color: #e67e22;
  }

  .poster-header .subtitle {
    font-size: 28px;
    font-weight: 400;
    color: #7b9ec4;
    margin-top: 18px;
    letter-spacing: 0.2px;
  }

  .poster-header .venue {
    font-size: 22px;
    font-weight: 500;
    color: #4a7099;
    margin-top: 12px;
    text-transform: uppercase;
    letter-spacing: 2px;
  }

  /* --- METRICS STRIP --- */
  .metrics-strip {
    display: flex;
    justify-content: space-around;
    padding: 40px 80px;
    background: linear-gradient(90deg, rgba(26,58,92,0.3), rgba(192,57,43,0.15), rgba(26,58,92,0.3));
    border-bottom: 1px solid rgba(26,58,92,0.4);
  }

  .metric-card {
    text-align: center;
    padding: 24px 32px;
    border-left: 1px solid rgba(123,158,196,0.2);
    flex: 1;
  }
  .metric-card:first-child { border-left: none; }

  .metric-card .metric-value {
    font-size: 38px;
    font-weight: 800;
    color: #ffffff;
    letter-spacing: -0.5px;
    line-height: 1.1;
  }

  .metric-card .metric-label {
    font-size: 16px;
    font-weight: 500;
    color: #7b9ec4;
    margin-top: 8px;
    text-transform: uppercase;
    letter-spacing: 0.8px;
  }

  .metric-card.highlight {
    background: rgba(230,126,34,0.12);
    border-radius: 6px;
  }
  .metric-card.highlight .metric-value {
    color: #e67e22;
  }

  /* --- CHART SECTION (Centerpiece) --- */
  .chart-section {
    flex: 1;
    display: flex;
    flex-direction: column;
    padding: 30px 80px 20px 80px;
    background: linear-gradient(180deg, rgba(13,31,60,0.6), rgba(10,22,40,0.8));
    min-height: 0;
  }

  .chart-section .chart-title {
    font-size: 36px;
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 8px;
  }

  .chart-section .chart-desc {
    font-size: 20px;
    font-weight: 400;
    color: #7b9ec4;
    margin-bottom: 20px;
  }

  .chart-container {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(10,22,40,0.4);
    border-radius: 8px;
    border: 1px solid rgba(26,58,92,0.3);
    padding: 20px;
    min-height: 0;
    overflow: hidden;
  }

  .chart-container svg {
    width: 100%;
    height: 100%;
  }

  /* --- TWO COLUMN CONTENT --- */
  .content-section {
    display: flex;
    padding: 40px 80px;
    gap: 50px;
    background: linear-gradient(180deg, rgba(10,22,40,0.8), rgba(8,14,24,0.95));
    border-top: 1px solid rgba(26,58,92,0.3);
  }

  .content-col {
    flex: 1;
  }

  .content-col .col-title {
    font-size: 28px;
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 20px;
    padding-bottom: 12px;
    border-bottom: 3px solid;
  }

  .col-why .col-title { border-color: #1a3a5c; }
  .col-policy .col-title { border-color: #c0392b; }

  .content-col .col-text {
    font-size: 20px;
    font-weight: 400;
    color: #bccfde;
    line-height: 1.6;
    margin-bottom: 18px;
  }

  .content-col .col-text strong {
    color: #ffffff;
    font-weight: 600;
  }

  .content-col .col-list {
    list-style: none;
    padding: 0;
  }

  .content-col .col-list li {
    font-size: 19px;
    font-weight: 400;
    color: #bccfde;
    line-height: 1.55;
    margin-bottom: 12px;
    padding-left: 24px;
    position: relative;
  }

  .content-col .col-list li::before {
    content: '';
    position: absolute;
    left: 0;
    top: 8px;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #1a3a5c;
  }

  .col-policy .col-list li::before {
    background: #c0392b;
  }

  /* --- BASELINE COMPARISON CALLOUT --- */
  .callout-box {
    background: linear-gradient(135deg, rgba(192,57,43,0.2), rgba(230,126,34,0.15));
    border: 1px solid rgba(230,126,34,0.4);
    border-radius: 8px;
    padding: 30px 35px;
    margin: 20px 0;
  }

  .callout-box .callout-heading {
    font-size: 22px;
    font-weight: 700;
    color: #e67e22;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 14px;
  }

  .callout-box .callout-body {
    font-size: 20px;
    color: #f0d0b0;
    line-height: 1.5;
  }

  .callout-box .callout-body .big-number {
    font-size: 48px;
    font-weight: 900;
    color: #e67e22;
    display: block;
    line-height: 1.1;
    margin: 6px 0;
  }

  /* --- TWO-UP COMPARISON --- */
  .compare-row {
    display: flex;
    gap: 20px;
    margin: 20px 0;
  }

  .compare-item {
    flex: 1;
    text-align: center;
    padding: 24px 16px;
    border-radius: 6px;
  }

  .compare-item.ipcc {
    background: rgba(26,58,92,0.3);
    border: 1px solid rgba(26,58,92,0.5);
  }

  .compare-item.true-baseline {
    background: rgba(192,57,43,0.2);
    border: 1px solid rgba(192,57,43,0.5);
  }

  .compare-item .compare-value {
    font-size: 42px;
    font-weight: 800;
    color: #ffffff;
    line-height: 1.1;
  }

  .compare-item .compare-label {
    font-size: 16px;
    font-weight: 500;
    color: #7b9ec4;
    margin-top: 6px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }

  .compare-item.true-baseline .compare-value {
    color: #e67e22;
  }

  /* --- FOOTER --- */
  .poster-footer {
    padding: 30px 100px;
    font-size: 16px;
    color: #4a7099;
    background: rgba(8,14,24,0.95);
    border-top: 1px solid rgba(26,58,92,0.3);
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  .poster-footer .ref {
    font-style: italic;
    max-width: 70%;
  }

  .poster-footer .doi {
    color: #7b9ec4;
  }

  /* SVG overrides for dark theme */
  .chart-container svg text {
    fill: #bccfde !important;
  }
  .chart-container svg [data-element="title"] text,
  .chart-container svg text[font-weight="bold"],
  .chart-container svg text[font-weight="700"] {
    fill: #ffffff !important;
  }
</style>
</head>
<body>

  <!-- HEADER -->
  <div class="poster-header">
    <div class="title">300 Years of Sclerosponge Thermometry Shows<br>Global Warming Has <em>Exceeded 1.5 °C</em></div>
    <div class="subtitle">Sclerosponge-derived sea-surface temperature records spanning three centuries reveal that total anthropogenic warming surpasses the Paris Agreement threshold when measured against a true pre-industrial baseline (1700–1790).</div>
    <div class="venue">AGU / Nature Climate Change Symposium &nbsp;|&nbsp; 2024</div>
  </div>

  <!-- METRICS STRIP -->
  <div class="metrics-strip">
    <div class="metric-card">
      <div class="metric-value">~300 yr</div>
      <div class="metric-label">Record Length</div>
    </div>
    <div class="metric-card">
      <div class="metric-value">~1.2 °C</div>
      <div class="metric-label">IPCC Reported Warming<br>(1850–1900 baseline)</div>
    </div>
    <div class="metric-card highlight">
      <div class="metric-value">+0.5 °C</div>
      <div class="metric-label">Hidden Pre-Industrial Warming</div>
    </div>
    <div class="metric-card highlight">
      <div class="metric-value">>1.5 °C</div>
      <div class="metric-label">Total Warming<br>(True Pre-Industrial Baseline)</div>
    </div>
    <div class="metric-card">
      <div class="metric-value">Sr/Ca</div>
      <div class="metric-label">Proxy Method</div>
    </div>
  </div>

  <!-- CHART (Centerpiece) -->
  <div class="chart-section">
    <div class="chart-title">300-Year Sea-Surface Temperature Reconstruction</div>
    <div class="chart-desc">Sclerosponge Sr/Ca paleothermometry (1700–2020) compared with instrumental records. The 1.5 °C Paris threshold is marked.</div>
    <div class="chart-container">
      ${cleanSVG}
    </div>
  </div>

  <!-- TWO-COLUMN CONTENT -->
  <div class="content-section">
    <div class="content-col col-why">
      <div class="col-title">Why Sclerosponges?</div>
      <div class="col-text">
        Sclerosponges are <strong>long-lived marine organisms</strong> found in tropical and subtropical oceans. As they grow, strontium-to-calcium (Sr/Ca) ratios in their aragonite skeletons faithfully track ambient water temperature.
      </div>
      <ul class="col-list">
        <li><strong>Continuous growth</strong> over centuries — unbroken annual-resolution records</li>
        <li><strong>Tropical ocean sensitivity</strong> — Caribbean sites capture large-scale SST variability</li>
        <li><strong>Independent of instrumental networks</strong>, which only begin around 1850</li>
        <li>Specimens collected from <strong>33–91 m depth</strong> in Caribbean reef environments</li>
        <li>Calibrated against co-located instrumental SST from 1960 onward (r² > 0.9)</li>
      </ul>

      <div class="callout-box">
        <div class="callout-heading">The Pre-Industrial Baseline Problem</div>
        <div class="callout-body">
          The IPCC operationally defines "pre-industrial" as <strong>1850–1900</strong>, but sclerosponge data show this period was already <strong>~0.5 °C</strong> above the true pre-industrial mean (1700–1790). This means <strong>conventional estimates systematically underestimate</strong> total anthropogenic warming by roughly half a degree.
        </div>
      </div>
    </div>

    <div class="content-col col-policy">
      <div class="col-title">Policy & Climate Target Implications</div>

      <div class="compare-row">
        <div class="compare-item ipcc">
          <div class="compare-value">~1.2 °C</div>
          <div class="compare-label">IPCC AR6<br>1850–1900 Baseline</div>
        </div>
        <div class="compare-item true-baseline">
          <div class="compare-value">~1.7 °C</div>
          <div class="compare-label">This Study<br>1700–1790 Baseline</div>
        </div>
      </div>

      <div class="callout-box" style="margin-top: 10px;">
        <div class="callout-heading">1.5 °C Has Already Been Exceeded</div>
        <div class="callout-body">
          <span class="big-number">>1.5 °C</span>
          The warming crossed the Paris Agreement's most ambitious guardrail in the early 2020s when measured against a true pre-industrial baseline.
        </div>
      </div>

      <ul class="col-list">
        <li><strong>Carbon budget for 1.5 °C → effectively zero</strong> when using the sclerosponge-informed baseline</li>
        <li><strong>2.0 °C guardrail is closer</strong> — only ~0.3 °C of additional warming remains (vs. ~0.8 °C under IPCC baseline)</li>
        <li><strong>Urgency of emissions reductions</strong> is greater than current policy timelines assume</li>
        <li>Findings underscore the need for <strong>transparent communication</strong> about how baselines shape perceived climate targets</li>
      </ul>

      <div class="col-text" style="margin-top: 18px; font-size: 18px;">
        <strong>Data & Methods Summary:</strong> Sr/Ca ratios measured via ICP-OES. Reconstruction validated against HadCRUT5 and NOAA ERSSTv5, showing excellent agreement during instrumental era and divergence before ~1850.
      </div>
    </div>
  </div>

  <!-- FOOTER -->
  <div class="poster-footer">
    <div class="ref">Reference: McCulloch, M.T., Winter, A., Sherman, C.E. et al. <em>300 years of sclerosponge thermometry shows global warming has exceeded 1.5 °C.</em> Nature Climate Change (2024).</div>
    <div class="doi">DOI: 10.1038/s41558-024-01968-y</div>
  </div>

</body>
</html>`;
}

async function main() {
  console.log('Building temperature chart via SSR...');
  const syntax = buildChartSyntax();
  const chartSVG = await renderToString(syntax, {
    width: 3800,
    height: 2000,
    themeConfig: {
      colorBg: '#0a1628',
      colorPrimary: '#1a3a5c',
      base: {
        text: { 'font-family': '"Inter", "Helvetica Neue", Arial, sans-serif', 'font-size': '22' }
      },
      title: { 'font-family': '"Inter", "Helvetica Neue", Arial, sans-serif', 'font-size': '32', fill: '#ffffff' },
      desc: { 'font-family': '"Inter", "Helvetica Neue", Arial, sans-serif', 'font-size': '20', fill: '#7b9ec4' }
    }
  });
  console.log('Chart SVG generated (' + chartSVG.length + ' bytes)');

  console.log('Building poster HTML...');
  const html = buildPosterHTML(chartSVG);
  const htmlPath = '/app/output/poster.html';
  fs.writeFileSync(htmlPath, html);
  console.log('Poster HTML written to ' + htmlPath);

  console.log('Rendering poster to PNG with Playwright...');
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.setViewportSize({ width: A0_W, height: A0_H });

  const fullUrl = 'file://' + path.resolve(htmlPath);
  await page.goto(fullUrl, { waitUntil: 'networkidle', timeout: 30000 });

  // Small delay for any async font rendering
  await page.waitForTimeout(2000);

  const pngPath = '/app/output/final_poster.png';
  await page.screenshot({ path: pngPath, fullPage: true, type: 'png' });
  console.log('Poster saved to ' + pngPath);

  await browser.close();
  console.log('Done.');
}

main().catch(e => { console.error(e); process.exit(1); });

