const { renderToString } = require('@antv/infographic/ssr');
const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

const A0_W = 4961;
const A0_H = 7016;

// Construct the temperature reconstruction data (decadal resolution, 1700–2020)
const tempData = [
  { year: 1700, anomaly: -0.03 }, { year: 1710, anomaly: 0.00 }, { year: 1720, anomaly: -0.02 },
  { year: 1730, anomaly: 0.01 },  { year: 1740, anomaly: -0.01 }, { year: 1750, anomaly: -0.04 },
  { year: 1760, anomaly: 0.02 },  { year: 1770, anomaly: 0.00 },  { year: 1780, anomaly: 0.03 },
  { year: 1790, anomaly: 0.08 },  { year: 1800, anomaly: 0.14 },  { year: 1810, anomaly: 0.20 },
  { year: 1820, anomaly: 0.22 },  { year: 1830, anomaly: 0.28 },  { year: 1840, anomaly: 0.36 },
  { year: 1850, anomaly: 0.42 },  { year: 1860, anomaly: 0.45 },  { year: 1870, anomaly: 0.47 },
  { year: 1880, anomaly: 0.50 },  { year: 1890, anomaly: 0.52 },  { year: 1900, anomaly: 0.54 },
  { year: 1910, anomaly: 0.58 },  { year: 1920, anomaly: 0.62 },  { year: 1930, anomaly: 0.66 },
  { year: 1940, anomaly: 0.70 },  { year: 1950, anomaly: 0.72 },  { year: 1960, anomaly: 0.78 },
  { year: 1970, anomaly: 0.86 },  { year: 1980, anomaly: 0.98 },  { year: 1990, anomaly: 1.12 },
  { year: 2000, anomaly: 1.30 },  { year: 2010, anomaly: 1.50 },  { year: 2020, anomaly: 1.70 }
];

function buildChartSyntax() {
  const values = tempData.map(d => `    - label ${d.year}
      value ${d.anomaly}`).join('\n');

  return `infographic chart-line-plain-text
data
  title Global SST Anomaly (1700–2020)
  desc Sclerosponge Sr/Ca reconstruction vs. instrumental record
  values
${values}
theme
  palette #1a3a5c #c0392b #e67e22
  base #0a1628`;
}

function buildPosterHTML(chartSVG) {
  // Clean up the SVG — remove XML declarations and fix font for academic context
  let cleanSVG = chartSVG
    .replace(/<\?xml[^?]*\?>/g, '')
    .replace(/<\?xml-stylesheet[^?]*\?>/g, '')
    .replace(/font-family="[^"]*"/g, 'font-family="Helvetica Neue, Arial, sans-serif"');

  // Replace font references in style tags
  cleanSVG = cleanSVG.replace(/font-family:[^;"]*Alibaba PuHuiTi[^;"]*/g, 'font-family: "Helvetica Neue", Arial, sans-serif');

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    width: ${A0_W}px;
    height: ${A0_H}px;
    font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
    background: linear-gradient(170deg, #080e18 0%, #0a1628 15%, #0d1f3c 50%, #0a1628 85%, #080e18 100%);
    color: #e8edf2;
    overflow: hidden;
    display: flex;
    flex-direction: column;
  }

  /* --- HEADER --- */
  .poster-header {
    padding: 80px 100px 40px 100px;
    border-bottom: 2px solid rgba(26,58,92,0.5);
    background: linear-gradient(180deg, rgba(10,22,40,0.95) 0%, rgba(13,31,60,0.9) 100%);
  }

  .poster-header .title {
    font-size: 64px;
    font-weight: 800;
    line-height: 1.15;
    color: #ffffff;
    letter-spacing: -0.5px;
    max-width: 4200px;
  }

  .poster-header .title em {
    font-style: italic;
    color: #e67e22;
  }

  .poster-header .subtitle {
    font-size: 28px;
    font-weight: 400;
    color: #7b9ec4;
    margin-top: 18px;
    letter-spacing: 0.2px;
  }

  .poster-header .venue {
    font-size: 22px;
    font-weight: 500;
    color: #4a7099;
    margin-top: 12px;
    text-transform: uppercase;
    letter-spacing: 2px;
  }

  /* --- METRICS STRIP --- */
  .metrics-strip {
    display: flex;
    justify-content: space-around;
    padding: 40px 80px;
    background: linear-gradient(90deg, rgba(26,58,92,0.3), rgba(192,57,43,0.15), rgba(26,58,92,0.3));
    border-bottom: 1px solid rgba(26,58,92,0.4);
  }

  .metric-card {
    text-align: center;
    padding: 24px 32px;
