    color: #7b9ec4;
    margin-top: 18px;
    letter-spacing: 0.2px;
  }

  .poster-header .venue {
    font-size: 22px;
    font-weight: 500;
    color: #4a7099;
    margin-top: 12px;
    text-transform: uppercase;
    letter-spacing: 2px;
  }

  /* --- METRICS STRIP --- */
  .metrics-strip {
    display: flex;
