  flex: 1;
  position: relative;
  min-height: 0;
}

.chart-container {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(180deg, #0d1f3c 0%, #0f2340 50%, #0d1f3c 100%);
  border-radius: 8px;
  border: 1px solid rgba(42,92,148,0.3);
  padding: 20px;
  overflow: hidden;
}

.chart-container svg {
  width: 100%;
  height: 100%;
}

/* Threshold line overlay */
.threshold-overlay {
  position: absolute;
  right: 0;
  width: 100%;
  display: flex;
  align-items: center;
  pointer-events: none;
  z-index: 5;
}

.threshold-line {
  flex: 1;
  height: 0;
  border-top: 2px dashed rgba(230,126,34,0.7);
}

.threshold-label {
  background: rgba(192,57,43,0.85);
  color: #ffffff;
  font-size: 18px;
  font-weight: 700;
  padding: 6px 16px;
  border-radius: 4px;
  white-space: nowrap;
  letter-spacing: 0.5px;
}

/* Period annotations below chart */
.chart-periods {
  display: flex;
  padding: 12px 80px 8px 80px;
  gap: 6px;
}

.chart-periods .period {
  flex: 1;
  text-align: center;
  font-size: 15px;
  font-weight: 500;
  color: #7b9ec4;
  padding: 8px 4px;
  border-radius: 4px;
}

.period.pre-industrial { background: rgba(74,158,255,0.1); color: #4a9eff; }
.period.onset { background: rgba(74,158,255,0.15); color: #7bafef; }
