node -e "
const fs = require('fs');
const html = fs.readFileSync('/app/output/poster.html', 'utf8');
const svgMatch = html.match(/<svg[\s\S]*?<\/svg>/);
if (svgMatch) {
  const svg = svgMatch[0];
  // Find viewBox
  const vbMatch = svg.match(/viewBox=\"([^\"]+)\"/);
  console.log('viewBox:', vbMatch ? vbMatch[1] : 'not found');
  // Find chart area (look for the main plot area rect or clip path)
  const clipMatch = svg.match(/clip-path[^>]*/g);
  console.log('Clip paths found:', clipMatch ? clipMatch.length : 0);
  // Find the data-polyline or main line path
  const lineMatch = svg.match(/<path[^>]*fill=\"none\"[^>]*d=\"[^\"]{0,200}/g);
  console.log('Line paths:', lineMatch ? lineMatch.slice(0,2).join('...') : 'none');
  // Find y-axis text labels (value labels)
  const yLabels = svg.match(/<text[^>]*>[0-9.-]+<\/text>/g);
  console.log('Y-axis labels:', yLabels ? yLabels.slice(0,10).join(', ') : 'none');
  // Find the transform/translate of the chart group
  const transforms = svg.match(/transform=\"translate\([^)]+\)\"/g);
  console.log('Transforms:', transforms ? transforms.slice(0,5).join(', ') : 'none');
  // Find rect elements to understand layout
  const rects = svg.match(/<rect[^>]*\/>/g);
  console.log('Rect elements:', rects ? rects.slice(0,5).join(', ') : 'none');
}
"

