function buildPosterHTML(chartSVG) {
  // --- Post-process SVG to add threshold line and annotations ---
  // The chart Y-axis: 0.0→240.667, 0.5→186.5, 1.0→132.333, 1.5→78.167, 2.0→24
  const thresholdY = 78.167;
  const chartLeft = 68;
  const chartRight = 4348;

  // Inject threshold line + label right before </svg>
  const thresholdAnnotation = `
  <g id="threshold-annotation">
    <path d="M ${chartLeft} ${thresholdY} L ${chartRight} ${thresholdY}"
          stroke="#e67e22" stroke-width="2.5" stroke-dasharray="12,6" opacity="0.9"/>
    <rect x="${chartRight - 320}" y="${thresholdY - 20}" width="310" height="28" rx="4"
          fill="#c0392b" opacity="0.9"/>
    <text x="${chartRight - 12}" y="${thresholdY - 2}" fill="#ffffff"
          font-size="16" font-weight="700" text-anchor="end" dominant-baseline="central"
          font-family="'Inter','Helvetica Neue',Arial,sans-serif">
      1.5 °C Paris Threshold
    </text>
  </g>`;

  let processedSVG = chartSVG.replace('</svg>', thresholdAnnotation + '\n</svg>');

  // Clean up the SVG — remove XML declarations and fix font for academic context
  let cleanSVG = processedSVG
    .replace(/<\?xml[^?]*\?>/g, '')
    .replace(/<\?xml-stylesheet[^?]*\?>/g, '')
    .replace(/font-family="[^"]*Alibaba[^"]*"/g, 'font-family="\'Inter\',\'Helvetica Neue\',Arial,sans-serif"');

  // Replace font references in style tags
  cleanSVG = cleanSVG.replace(/font-family:[^;"']*Alibaba PuHuiTi[^;"']*/g, 'font-family: "Inter","Helvetica Neue",Arial,sans-serif');

