  { year: 1730, anomaly: 0.01 },  { year: 1740, anomaly: -0.01 }, { year: 1750, anomaly: -0.04 },
  { year: 1760, anomaly: 0.02 },  { year: 1770, anomaly: 0.00 },  { year: 1780, anomaly: 0.03 },
  { year: 1790, anomaly: 0.08 },  { year: 1800, anomaly: 0.14 },  { year: 1810, anomaly: 0.20 },
  { year: 1820, anomaly: 0.22 },  { year: 1830, anomaly: 0.28 },  { year: 1840, anomaly: 0.36 },
  { year: 1850, anomaly: 0.42 },  { year: 1860, anomaly: 0.45 },  { year: 1870, anomaly: 0.47 },
  { year: 1880, anomaly: 0.50 },  { year: 1890, anomaly: 0.52 },  { year: 1900, anomaly: 0.54 },
  { year: 1910, anomaly: 0.58 },  { year: 1920, anomaly: 0.62 },  { year: 1930, anomaly: 0.66 },
  { year: 1940, anomaly: 0.70 },  { year: 1950, anomaly: 0.72 },  { year: 1960, anomaly: 0.78 },
  { year: 1970, anomaly: 0.86 },  { year: 1980, anomaly: 0.98 },  { year: 1990, anomaly: 1.12 },
  { year: 2000, anomaly: 1.30 },  { year: 2010, anomaly: 1.50 },  { year: 2020, anomaly: 1.70 }
];
const values = tempData.map(d => '    - label ' + d.year + '\\n      value ' + d.anomaly).join('\\n');
const syntax = 'infographic chart-line-plain-text\\ndata\\n  title Global SST Anomaly (1700-2020)\\n  desc Reconstruction with 1.5 C Paris Agreement threshold\\n  values\\n' + values + '\\ntheme\\n  palette #4a9eff #e67e22 #c0392b\\n  base #0d1f3c';
(async () => {
  // Test different font sizes
  for (const fs of [12, 22, 32]) {
    const svg = await renderToString(syntax, {
      width: 2800, height: 1200,
      themeConfig: {
        base: { text: { 'font-size': '' + fs } },
        title: { 'font-size': '' + (fs+10) },
        desc: { 'font-size': '' + (fs-2) },
        item: { label: { 'font-size': '' + fs }, value: { 'font-size': '' + fs } }
      }
    });
    const vb = svg.match(/viewBox=\"([^\"]+)\"/)[1];
    const [, , w, h] = vb.split(' ');
    console.log('font-size', fs, '-> viewBox', w, 'x', h, 'ratio', (parseFloat(w)/parseFloat(h)).toFixed(1));
  }
})();
"

