node -e "
const fs = require('fs');
const html = fs.readFileSync('/app/output/poster.html', 'utf8');
const buf = fs.readFileSync('/app/output/final_poster.png');

// Basic checks
console.log('=== POSTER VERIFICATION ===');
console.log('PNG dimensions:', buf.readUInt32BE(16), 'x', buf.readUInt32BE(20));
console.log('PNG file size:', (buf.length/1024/1024).toFixed(1), 'MB');

// Check viewBox expanded
const vb = html.match(/viewBox=\"([^\"]+)\"/);
console.log('SVG viewBox:', vb ? vb[1] : 'MISSING');

// Structural checks
const checks = [
  ['Title', '300 Years of Sclerosponge Thermometry'],
  ['1.5C crossed', 'Exceeded 1.5'],
  ['Metrics - 300yr', '~300 yr'],
  ['Metrics - IPCC 1.2', '~1.2 °C'],
  ['Metrics - Hidden 0.5', '+0.5 °C'],
  ['Metrics - True >1.5', '>1.5 °C'],
  ['Metrics - Sr/Ca', 'Sr/Ca'],
  ['Threshold annotation', '1.5 °C Paris Threshold'],
  ['Period annotations', '1700–1790'],
  ['IPCC baseline period', '1850–1900'],
  ['Exceeded period', '2000–Present'],
  ['Why Sclerosponges', 'Why Sclerosponges'],
  ['Policy implications', 'Policy & Climate Target'],
  ['1.2 vs 1.7 comparison', '~1.7 °C'],
  ['Data & Methods', 'Data & Methods Summary'],
  ['Reference', 'Nature Climate Change (2024)'],
  ['DOI', '10.1038/s41558-024-01968-y'],
];

let allPass = true;
for (const [name, search] of checks) {
  const found = html.includes(search);
  if (!found) { console.log('MISSING:', name); allPass = false; }
}
if (allPass) console.log('All', checks.length, 'content checks passed');

// Check chart data points
for (const year of [1700, 1750, 1800, 1850, 1900, 1950, 2000, 2010, 2020]) {
  if (!html.includes('' + year)) console.log('MISSING year:', year);
}
console.log('All key years present in chart data');
"

